old = src[src.index("def rand_expr(rng, alphabet, depth=0):"):src.index("def main():")]
new = '''def rand_expr(rng, alphabet, state, depth=0):
    r = rng.random()
    if depth > 2 or r < 0.35:
        op = rng.choice(["match", "startswith", "endswith", "contains"])
        n = rng.randint(0, 3)
        path = [rng.choice(alphabet) for _ in range(n)] if alphabet else []
        key = (op, tuple(path))
        if key not in state["atoms"] and len(state["atoms"]) >= 10:
            return {"op": "true"}
        state["atoms"].add(key)
        return {"op": op, "path": path}
    if r < 0.45:
        return {"op": rng.choice(["true", "false"])}
    if r < 0.6:
        return {"op": "not", "arg": rand_expr(rng, alphabet, state, depth + 1)}
    op = rng.choice(["and", "or"])
    n = rng.randint(0, 3)
    return {"op": op, "args": [rand_expr(rng, alphabet, state, depth + 1) for _ in range(n)]}


'''
